import {styles,colors,types,combinations,illustration,demoPieces} from './engine.mjs';
import {newPieceId} from './piece-id.mjs';
const $=s=>document.querySelector(s), icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let db,user=null,csrf='',config={},catalog=structuredClone(demoPieces),pieces=[],favorites=[],activeStyle='Rock',activeType='all',collection='mine',offset=0,pendingPhoto=null,photoBusy=false,photoVersion=0,saveBusy=false,guest=false,importQueue=[],importIndex=0,pickerActive=false;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500)}
async function api(path,{method='GET',data}={}){let response;try{response=await fetch('/api/'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json',...(method!=='GET'?{'X-Youfit-CSRF':csrf}:{})},...(data!==undefined?{body:JSON.stringify(data)}:{})})}catch{throw Error('Sem conexão com o servidor. Tente novamente.')}const body=await response.json().catch(()=>({error:'O servidor do aplicativo não está disponível.'}));if(!response.ok)throw Object.assign(Error(body.error||'Não foi possível concluir.'),{status:response.status});return body}
async function localDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('youfit',1);req.onupgradeneeded=()=>req.result.createObjectStore('state');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function localRead(){return new Promise((resolve,reject)=>{const req=db.transaction('state').objectStore('state').get('wardrobe');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function persist(nextPieces=pieces,nextFavorites=favorites){if(user)return api('wardrobe',{method:'PUT',data:{pieces:nextPieces,favorites:nextFavorites}});return new Promise((resolve,reject)=>{if(!db)return reject(Error('O armazenamento está indisponível neste navegador.'));const tx=db.transaction('state','readwrite');tx.objectStore('state').put({pieces:nextPieces,favorites:nextFavorites},'wardrobe');tx.oncomplete=resolve;tx.onerror=()=>reject(Error('Não foi possível salvar. Verifique o espaço do navegador.'));tx.onabort=()=>reject(Error('Não foi possível salvar.'))})}
async function commit(nextPieces,nextFavorites=favorites){if(saveBusy)throw Error('Aguarde o salvamento anterior.');saveBusy=true;try{await persist(nextPieces,nextFavorites);pieces=nextPieces;favorites=nextFavorites;render()}finally{saveBusy=false}}
async function enterGuest(){guest=true;user=null;try{sessionStorage.setItem('youfit-demo','1');db??=await localDB();const saved=await localRead();if(saved){pieces=saved.pieces.filter(p=>!p.demo||catalog.some(c=>c.id===p.id)).map(p=>p.demo?catalog.find(c=>c.id===p.id):p);favorites=saved.favorites.filter(id=>id.split('|').slice(0,3).every(key=>pieces.some(p=>p.id===key)))}else{pieces=structuredClone(catalog);favorites=[];await persist()}}catch{pieces=structuredClone(catalog);favorites=[];toast('Modo temporário: o navegador não permitiu salvar dados.')}location.hash='looks';route();render()}
async function enterUser(account){user=account;guest=false;sessionStorage.removeItem('youfit-demo');const saved=await api('wardrobe');pieces=saved.pieces;favorites=saved.favorites;collection='mine';$('#auth-form').reset();location.hash='looks';route();render()}
function route(){const page=location.hash.slice(1)||'login';const auth=['login','signup'].includes(page);if(!auth&&!user&&!guest){location.hash='login';return}$('#auth-screen').hidden=!auth;$('#app-screen').hidden=auth;if(auth){const signup=page==='signup';$('#auth-title').innerHTML=signup?'Seu estilo.<br><span>Seu cantinho.</span>':'Vista seu <span>mood.</span>';$('#auth-description').textContent=signup?'Crie sua conta e dê uma nova vida às suas peças.':'Seus looks favoritos começam com o que você já tem.';$('#name-label').hidden=!signup;$('#auth-name').required=signup;$('#password-hint').hidden=!signup;$('#auth-password').autocomplete=signup?'new-password':'current-password';$('#auth-submit').innerHTML=(signup?'Criar meu cantinho':'Entrar no meu armário')+icon('arrow');$('#login-tab').classList.toggle('active',!signup);$('#signup-tab').classList.toggle('active',signup);$('#auth-error').textContent='';document.title=(signup?'Criar conta':'Entrar')+' · YOUFIT'}else{const view=['looks','wardrobe','saved','profile'].includes(page)?page:'looks';for(const v of ['looks','wardrobe','saved','profile'])$(`#${v}-view`).hidden=v!==view;document.querySelectorAll('.bottom-nav [data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});document.title=({looks:'Seu mood',wardrobe:'Meu armário',saved:'Favoritos',profile:'Meu espaço'})[view]+' · YOUFIT'}window.scrollTo(0,0)}
window.addEventListener('hashchange',route);
function garment(p){return `<div class="garment">${p.photo?`<img src="${esc(p.photo)}" alt="${esc(p.name)}" loading="lazy">`:illustration(p.type,p.color)}</div>`}
const vibe={Rock:['ϟ','#eadff7'],Casual:['☀','#f8eac0'],Esportivo:['↗','#daeee3'],Elegante:['◇','#f8dfe5'],Streetwear:['✳','#e0e9fa']};
function card(look,index){const saved=favorites.includes(look.id);return `<article class="look-card"><div class="look-art" style="background:${['#f0e7f4','#e9eee5','#f8e9df'][index%3]}"><span class="look-tag">${vibe[look.style][0]} ${esc(look.style.toUpperCase())}</span>${look.pieces.map(garment).join('')}<button class="heart ${saved?'selected':''}" data-favorite="${esc(look.id)}" aria-label="${saved?'Remover dos':'Adicionar aos'} favoritos" aria-pressed="${saved}">${icon('heart')}</button></div><div class="look-copy"><h3>${esc(({Rock:'Um pouquinho de atitude',Casual:'Leve, livre e do seu jeito',Esportivo:'Energia pra acompanhar você',Elegante:'Seu momento de brilhar',Streetwear:'A rua é sua passarela'})[look.style])}</h3><p>${look.pieces.map(p=>esc(p.name)).join(' + ')}</p><p class="reason">✧ ${esc(look.reason)}</p>${look.pieces.some(p=>p.demo)?'<p class="catalog-label">Com peças de exemplo do catálogo real</p>':''}</div></article>`}
function empty(title,text,action=''){return `<div class="empty"><div class="empty-icon">✳</div><h3>${title}</h3><p>${text}</p>${action}</div>`}
function render(){
 $('#count').textContent=pieces.length;$('#saved-count').textContent=favorites.length;$('#saved-count').hidden=!favorites.length;
 $('#styles').innerHTML=styles.map(s=>`<button class="${s===activeStyle?'active':''}" data-style="${s}" aria-pressed="${s===activeStyle}" style="--chip-bg:${vibe[s][1]}"><span aria-hidden="true">${vibe[s][0]}</span>${s}</button>`).join('');
 $('#types').innerHTML=Object.entries({all:'Tudo',...types}).map(([id,name])=>`<button class="${id===activeType?'active':''}" data-type="${id}" aria-pressed="${id===activeType}">${name}</button>`).join('');
 const looks=combinations(pieces,activeStyle),shown=looks.length?Array.from({length:Math.min(4,looks.length)},(_,i)=>looks[(offset+i)%looks.length]):[];
 $('#result-count').textContent=`${looks.length} ${looks.length===1?'match encontrado':'matches encontrados'} no seu armário`;
 $('#looks').innerHTML=shown.length?shown.map(card).join(''):empty('Bora fazer um match?','Adicione parte de cima, parte de baixo e calçado. Marque a vibe em pelo menos duas peças.',`<button class="secondary" data-add>Adicionar uma peça ${icon('plus')}</button><button class="text-button" data-show-catalog>Explorar o catálogo real ↗</button>`);
 $('#shuffle').disabled=looks.length<2;$('#demo-note').hidden=!pieces.some(p=>p.demo);
 const query=$('#search').value.trim().toLocaleLowerCase('pt-BR');const source=collection==='catalog'?catalog:pieces;const filtered=source.filter(p=>(activeType==='all'||p.type===activeType)&&(!query||`${p.name} ${p.color} ${p.styles.join(' ')}`.toLocaleLowerCase('pt-BR').includes(query)));
 document.querySelectorAll('[data-collection]').forEach(b=>{b.classList.toggle('active',b.dataset.collection===collection);b.setAttribute('aria-pressed',b.dataset.collection===collection)});
 $('#collection-note').textContent=collection==='catalog'?'7 peças reais para experimentar. Adicione ao armário apenas as peças que você também tem.':guest?'Modo exploração: as peças iniciais são exemplos. Suas fotos ficam apenas neste navegador.':`${pieces.length} peças no seu espaço. Fotografe suas roupas ou importe do Google Fotos.`;
 $('#wardrobe').innerHTML=filtered.length?filtered.map(p=>`<article class="piece-card">${garment(p)}<div class="piece-info"><h3>${esc(p.name)}</h3><p><span class="piece-color" style="background:${colors[p.color]}"></span>${esc(types[p.type])} · ${esc(p.color)}</p><p>${p.styles.map(esc).join(' · ')}</p>${p.catalog?'<p class="piece-source">Foto real · catálogo YOUFIT</p>':''}${collection==='catalog'?`<button data-add-catalog="${p.id}" ${pieces.some(x=>x.id===p.id)?'disabled':''}>${pieces.some(x=>x.id===p.id)?'Já está no armário':'＋ Tenho essa peça'}</button>`:`<button data-delete="${esc(p.id)}">Remover do armário</button>`}</div></article>`).join(''):empty(query?'Cadê essa peça?':'Seu cantinho tá esperando!',query?'Tente outro nome, cor ou filtro.':'Uma foto da sua roupa é o primeiro passo para novos looks.',query?'':`<button class="secondary" data-add>Adicionar peça ${icon('plus')}</button>`);
 const saved=styles.flatMap(s=>combinations(pieces,s)).filter(l=>favorites.includes(l.id));$('#saved').innerHTML=saved.length?saved.map(card).join(''):empty('Os crushes moram aqui.','Toque no coração de um look e guarde esse match para depois.');
 const firstName=user?.name.split(' ')[0]||'explorador(a)';$('#hello').textContent=`Oi, ${firstName}!`;$('#profile-button').textContent=user?user.name[0].toUpperCase():'Y';$('#profile-avatar').textContent=user?user.name[0].toUpperCase():'Y';$('#profile-name').textContent=user?.name||'Modo exploração';$('#profile-email').textContent=user?.email||'Conheça as possibilidades do seu armário.';$('#account-status').textContent=user?'MEU CANTINHO NO YOUFIT':'DEMONSTRAÇÃO LOCAL';$('#logout-label').textContent=user?'Sair da minha conta':'Entrar ou criar uma conta';$('#storage-note').textContent=user?'Suas peças e seus favoritos ficam salvos na sua conta, neste servidor.':'Seus dados de demonstração ficam neste navegador. Exporte um backup antes de limpar os dados.';$('#photos-config-note').textContent=config.googleConfigured?'Importe só as fotos que você escolher.': 'Conexão disponível após configurar o Google Cloud.';
}
function showPiece(photo=null){photoVersion++;$('#piece-form').reset();pendingPhoto=photo;$('#photo-preview').hidden=!photo;$('#photo-label').hidden=Boolean(photo);if(photo)$('#photo-preview').src=photo;$('#form-error').textContent='';$('#piece-eyebrow').textContent=importQueue.length?`FOTO ${importIndex+1} DE ${importQueue.length} · GOOGLE FOTOS`:'NOVA PEÇA, NOVOS MATCHES';$('#skip-import').hidden=!importQueue.length;$('#save-piece').disabled=false;$('#piece-dialog').showModal()}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-add')){importQueue=[];showPiece()}
 if(b.dataset.view)location.hash=b.dataset.view;
 if(b.hasAttribute('data-show-catalog')){collection='catalog';location.hash='wardrobe';render()}
 if(b.dataset.style){activeStyle=b.dataset.style;offset=0;render()}
 if(b.dataset.type){activeType=b.dataset.type;render()}
 if(b.dataset.collection){collection=b.dataset.collection;render()}
 if(b.dataset.favorite){const id=b.dataset.favorite,next=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];try{await commit(pieces,next);toast(next.includes(id)?'Match salvo! Ele já tá nos favoritos.':'Look removido dos favoritos.')}catch(err){toast(err.message)}}
 if(b.dataset.delete){const piece=pieces.find(p=>p.id===b.dataset.delete);if(!piece||!confirm(`Remover “${piece.name}” do armário? Os favoritos com essa peça também serão removidos.`))return;try{await commit(pieces.filter(p=>p.id!==piece.id),favorites.filter(id=>!id.split('|').slice(0,3).includes(piece.id)));toast('Peça removida do armário.')}catch(err){toast(err.message)}}
 if(b.dataset.addCatalog){const item=catalog.find(p=>p.id===b.dataset.addCatalog);if(!item||pieces.some(p=>p.id===item.id))return;try{await commit([...pieces,{...item,demo:false}]);toast('Pronto! Essa peça agora faz parte do seu armário.')}catch(err){toast(err.message)}}
});
$('#search').oninput=render;$('#profile-button').onclick=()=>location.hash='profile';$('#shuffle').onclick=()=>{const n=combinations(pieces,activeStyle).length;offset=(offset+4)%Math.max(1,n);if(!offset&&n<=4)offset=1;render()};
$('#close-dialog').onclick=()=>$('#piece-dialog').close();$('#piece-dialog').addEventListener('close',()=>{photoVersion++;importQueue=[];importIndex=0;photoBusy=false});
async function resizePhoto(file){if(file.size>12*1024*1024)throw Error('Escolha uma imagem com até 12 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Use uma foto JPG, PNG ou WebP.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,800/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fcfaf7';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',.8)}
async function acceptPhoto(file){if(!file)return;const version=++photoVersion;photoBusy=true;$('#save-piece').disabled=true;$('#form-error').textContent='Preparando sua foto…';try{const photo=await resizePhoto(file);if(version!==photoVersion)return;pendingPhoto=photo;$('#photo-preview').src=photo;$('#photo-preview').hidden=false;$('#photo-label').hidden=true;$('#form-error').textContent=''}catch(err){if(version===photoVersion){pendingPhoto=null;$('#photo-preview').hidden=true;$('#photo-label').hidden=false;$('#form-error').textContent=err.message}}finally{if(version===photoVersion){photoBusy=false;$('#save-piece').disabled=false}}}
$('#take-photo').onclick=()=>$('#photo').click();$('#choose-photo').onclick=()=>$('#gallery-photo').click();$('#photo').onchange=e=>acceptPhoto(e.target.files[0]);$('#gallery-photo').onchange=e=>acceptPhoto(e.target.files[0]);
function nextImported(){importIndex++;if(importIndex<importQueue.length){const photo=importQueue[importIndex];showPiece(photo)}else{$('#piece-dialog').close();toast('Prontinho! Suas fotos viraram novas possibilidades.')}}
$('#skip-import').onclick=nextImported;
$('#piece-form').onsubmit=async e=>{e.preventDefault();if(photoBusy||saveBusy)return;const name=$('#piece-name').value.trim(),selected=[...document.querySelectorAll('[name="styles"]:checked')].map(c=>c.value);if(!name||!pendingPhoto||!selected.length){$('#form-error').textContent='Adicione uma foto, um nome e pelo menos uma vibe.';return}$('#save-piece').disabled=true;const p={id:newPieceId(),name,type:$('#piece-type').value,color:$('#piece-color').value,styles:selected,photo:pendingPhoto,demo:false,source:importQueue.length?'google-photos':'upload'};try{await commit([...pieces,p]);if(importQueue.length)nextImported();else{$('#piece-dialog').close();toast('Peça salva. Bora encontrar novos matches!')}}catch(err){$('#form-error').textContent=err.message}finally{$('#save-piece').disabled=false}};
$('#piece-color').innerHTML=Object.keys(colors).map(c=>`<option value="${c}">${c[0].toUpperCase()+c.slice(1)}</option>`).join('');$('#style-options').innerHTML=styles.map(s=>`<label><input type="checkbox" name="styles" value="${s}"> ${s}</label>`).join('');
$('#explore-demo').onclick=enterGuest;$('#google-placeholder').onclick=()=>$('#google-hint').hidden=false;
$('#toggle-password').onclick=()=>{const show=$('#auth-password').type==='password';$('#auth-password').type=show?'text':'password';$('#toggle-password').textContent=show?'Ocultar':'Mostrar';$('#toggle-password').setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha')};
$('#auth-form').onsubmit=async e=>{e.preventDefault();$('#auth-error').textContent='';$('#auth-submit').disabled=true;const signup=location.hash==='#signup';try{const result=await api('auth/'+(signup?'register':'login'),{method:'POST',data:{name:$('#auth-name').value.trim(),email:$('#auth-email').value.trim(),password:$('#auth-password').value}});await enterUser(result.user);toast(signup?'Seu cantinho tá pronto. Bem-vindo(a)!':'Que bom ter você de volta!')}catch(err){$('#auth-error').textContent=err.message}finally{$('#auth-submit').disabled=false}};
$('#logout').onclick=async()=>{try{if(user)await api('auth/logout',{method:'POST'});user=null;guest=false;pieces=[];favorites=[];sessionStorage.removeItem('youfit-demo');location.hash='login';route()}catch(err){toast(err.message)}};
$('#backup').onclick=()=>{const blob=new Blob([JSON.stringify({version:2,pieces,favorites},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='youfit-meu-armario.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exportado com fotos e favoritos.')};
let googleReady=false,tokenClient;
async function loadGoogle(){if(!config.googleConfigured)return;await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.async=true;s.onload=resolve;s.onerror=reject;document.head.append(s)});googleReady=true;google.accounts.id.initialize({client_id:config.googleClientId,nonce:csrf,auto_select:false,callback:async response=>{try{const result=await api('auth/google',{method:'POST',data:{credential:response.credential}});await enterUser(result.user);toast('Seu Google e seu estilo, juntos por aqui.')}catch(err){$('#auth-error').textContent=err.message}}});google.accounts.id.renderButton($('#google-button'),{type:'standard',theme:'outline',size:'large',shape:'pill',text:'continue_with',width:Math.max(200,Math.min(350,$('#google-button').clientWidth||260)),locale:'pt-BR'});$('#google-placeholder').hidden=true;}
function openPhotos(){if($('#piece-dialog').open)$('#piece-dialog').close();$('#photos-error').textContent='';$('#photos-start').hidden=false;$('#photos-check').hidden=!pickerActive;$('#picker-link').hidden=!pickerActive;$('#photos-start').disabled=!user||!config.googleConfigured||!googleReady;$('#photos-description').textContent=!user?'Entre na sua conta para importar do Google Fotos. Você também pode usar a galeria no modo exploração.':!config.googleConfigured?'A integração está preparada. A conexão será liberada depois da configuração do projeto no Google Cloud.':'Escolha até 20 fotos de peças no Google Fotos. Ao voltar, confirme a seleção aqui.';$('#photos-dialog').showModal()}
for(const selector of ['#connect-photos','#wardrobe-photos','#piece-google-photos'])$(selector).onclick=openPhotos;
$('#close-photos').onclick=async()=>{$('#photos-dialog').close();if(pickerActive){await api('photos/disconnect',{method:'POST'}).catch(()=>{});pickerActive=false}};
$('#photos-dialog').addEventListener('cancel',()=>{if(pickerActive){api('photos/disconnect',{method:'POST'}).catch(()=>{});pickerActive=false}});
$('#photos-fallback').onclick=()=>{$('#photos-dialog').close();if(pickerActive){api('photos/disconnect',{method:'POST'}).catch(()=>{});pickerActive=false}importQueue=[];showPiece();$('#gallery-photo').click()};
$('#photos-start').onclick=()=>{if(!googleReady||!user)return;$('#photos-error').textContent='';tokenClient=google.accounts.oauth2.initTokenClient({client_id:config.googleClientId,scope:'https://www.googleapis.com/auth/photospicker.mediaitems.readonly',include_granted_scopes:false,callback:async response=>{if(response.error){$('#photos-error').textContent='A conexão não foi autorizada. Você pode tentar novamente.';return}$('#photos-start').disabled=true;try{const session=await api('photos/start',{method:'POST',data:{accessToken:response.access_token,expiresIn:response.expires_in}});const url=new URL(session.pickerUri);if(url.protocol!=='https:'||url.hostname!=='photos.google.com')throw Error('O endereço de seleção não foi reconhecido.');pickerActive=true;$('#picker-link').href=session.pickerUri;$('#picker-link').hidden=false;$('#photos-check').hidden=false;$('#photos-start').hidden=true;$('#photos-description').textContent='Abra a seleção, escolha as fotos e toque em Concluído no Google Fotos. Depois volte aqui.'}catch(err){$('#photos-error').textContent=err.message}finally{$('#photos-start').disabled=false}},error_callback:()=>{$('#photos-error').textContent='A janela do Google foi fechada ou bloqueada. Tente novamente.'}});tokenClient.requestAccessToken({prompt:'consent'})};
$('#photos-check').onclick=async()=>{$('#photos-check').disabled=true;$('#photos-error').textContent='';try{const result=await api('photos/selection');if(!result.ready){$('#photos-error').textContent='A seleção ainda não foi concluída no Google Fotos.';return}const queue=[];for(const [index,item]of result.items.entries()){$('#photos-description').textContent=`Preparando foto ${index+1} de ${result.items.length}…`;const response=await fetch('/api/photos/image/'+encodeURIComponent(item.id),{credentials:'same-origin'});if(!response.ok)throw Error('Não foi possível baixar uma das fotos. Tente novamente.');queue.push(await resizePhoto(await response.blob()))}await api('photos/disconnect',{method:'POST'});pickerActive=false;$('#photos-dialog').close();if(!queue.length){toast('Nenhuma foto foi selecionada. Vídeos não são importados.');return}importQueue=queue;importIndex=0;showPiece(importQueue[0])}catch(err){$('#photos-error').textContent=err.message}finally{$('#photos-check').disabled=false}};
$('#credits-button').onclick=async()=>{try{const response=await fetch('assets/credits.json');if(!response.ok)throw Error();const credits=await response.json();$('#credits-list').innerHTML=credits.filter(c=>catalog.some(p=>p.photo===c.file)).map(c=>`<article><img src="${esc(c.file)}" alt=""><div><p><b>${esc(c.author)}</b></p><p><a href="${esc(c.source)}" target="_blank" rel="noopener">Foto original</a> · <a href="${esc(c.licenseUrl)}" target="_blank" rel="noopener">${esc(c.license)}</a></p><p>${esc(c.changes)}</p></div></article>`).join('');$('#credits-dialog').showModal()}catch{toast('Não foi possível abrir os créditos agora.')}};$('#close-credits').onclick=()=>$('#credits-dialog').close();
try{config=await api('bootstrap');csrf=config.csrf;if(config.user){await enterUser(config.user)}else if(sessionStorage.getItem('youfit-demo')&&!['#login','#signup'].includes(location.hash)){await enterGuest()}const result=await api('catalog');catalog=result.pieces;loadGoogle().catch(()=>{$('#google-hint').hidden=false;$('#google-hint').textContent='Não foi possível carregar o Google agora. Você pode continuar com seu e-mail.'})}catch{toast('Servidor indisponível. Você ainda pode explorar a demonstração.')}route();render();
